}

closed spec fn places_ok(v: Seq<PlaceToFree>, i: int) -> bool {
    0 <= i && i+1 < v.len()
        && 0 <= v[i].row < HEIGHT
        && 0 <= v[i].col < WIDTH
        && v[i].row != v[i+1].row
        && (v[i].row == hash1(v[i].key) || v[i].row == hash2(v[i].key))
        && (v[i+1].row == hash1(v[i].key) || v[i+1].row == hash2(v[i].key))
}


