#[inductive(delete_key_value)]
fn delete_key_value_inductive(pre: Self, post: Self, key: Key, row: Row, col: Col) {
    assert forall |k: Key| (#[trigger] post.frag[k]).is_some() implies
        exists |r: Row, c: Col|
            0 <= r < HEIGHT && 0 <= c < WIDTH
            && (#[trigger] post.matrix[r][c]).is_some()
            && post.matrix[r][c].unwrap().0 == k
    by {
        if post.frag[k].is_some() {
            // post.frag[key] == None, so k != key
            assert(k != key);
            // by pre invariant: exists r', c' with pre.matrix[r'][c'] = Some((k, _))
            let r_wit = choose |r: Row| exists |c: Col| 0 <= r < HEIGHT && 0 <= c < WIDTH
                && pre.matrix[r][c].is_some() && pre.matrix[r][c].unwrap().0 == k;
            let c_wit = choose |c: Col| 0 <= r_wit < HEIGHT && 0 <= c < WIDTH
                && pre.matrix[r_wit][c].is_some() && pre.matrix[r_wit][c].unwrap().0 == k;
            // pre.matrix[row][col].unwrap().0 == key and k != key, so by all_distinct
            // r_wit != row or c_wit != col
            assert(r_wit != row || c_wit != col) by {
                if r_wit == row && c_wit == col {
                    // pre.matrix[row][col].unwrap().0 == key
                    // pre.matrix[r_wit][c_wit].unwrap().0 == k
                    // But r_wit == row and c_wit == col, so key == k, contradiction
                    assert(pre.matrix[row][col].unwrap().0 == key);
                    assert(pre.matrix[r_wit][c_wit].unwrap().0 == k);
                    assert(false);
                }
            };
            // post.matrix[r_wit][c_wit] == pre.matrix[r_wit][c_wit]
            assert(post.matrix[r_wit][c_wit] == pre.matrix[r_wit][c_wit]);
        }
    };
}

#[inductive(update_key_value)]
fn update_key_value_inductive(pre: Self, post: Self, key: Key, new_val: Value, row: Row, col: Col) {
    assert forall |k: Key| (#[trigger] post.frag[k]).is_some() implies
        exists |r: Row, c: Col|
            0 <= r < HEIGHT && 0 <= c < WIDTH
            && (#[trigger] post.matrix[r][c]).is_some()
            && post.matrix[r][c].unwrap().0 == k
    by {
        if post.frag[k].is_some() {
            if k == key {
                // post.matrix[row][col] = Some((key, new_val))
                assert(post.matrix[row][col] == Some((key, new_val)));
            } else {
                // by pre invariant
                let r_wit = choose |r: Row| exists |c: Col| 0 <= r < HEIGHT && 0 <= c < WIDTH
                    && pre.matrix[r][c].is_some() && pre.matrix[r][c].unwrap().0 == k;
                let c_wit = choose |c: Col| 0 <= r_wit < HEIGHT && 0 <= c < WIDTH
                    && pre.matrix[r_wit][c].is_some() && pre.matrix[r_wit][c].unwrap().0 == k;
                assert(r_wit != row || c_wit != col) by {
                    if r_wit == row && c_wit == col {
                        assert(pre.matrix[row][col].unwrap().0 == key);
                        assert(pre.matrix[r_wit][c_wit].unwrap().0 == k);
                        assert(false);
                    }
                };
                assert(post.matrix[r_wit][c_wit] == pre.matrix[r_wit][c_wit]);
            }
        }
    };
}

#[inductive(insert_key_value)]
fn insert_key_value_inductive(pre: Self, post: Self, key: Key, new_val: Value, row: Row, col: Col) {
    assert forall |k: Key| (#[trigger] post.frag[k]).is_some() implies
        exists |r: Row, c: Col|
            0 <= r < HEIGHT && 0 <= c < WIDTH
            && (#[trigger] post.matrix[r][c]).is_some()
            && post.matrix[r][c].unwrap().0 == k
    by {
        if post.frag[k].is_some() {
            if k == key {
                // post.matrix[row][col] = Some((key, new_val))
                assert(post.matrix[row][col] == Some((key, new_val)));
            } else {
                // by pre invariant
                let r_wit = choose |r: Row| exists |c: Col| 0 <= r < HEIGHT && 0 <= c < WIDTH
                    && pre.matrix[r][c].is_some() && pre.matrix[r][c].unwrap().0 == k;
                let c_wit = choose |c: Col| 0 <= r_wit < HEIGHT && 0 <= c < WIDTH
                    && pre.matrix[r_wit][c].is_some() && pre.matrix[r_wit][c].unwrap().0 == k;
                // pre.matrix[row][col] == None (from transition), so r_wit != row or c_wit != col
                assert(r_wit != row || c_wit != col) by {
                    if r_wit == row && c_wit == col {
                        assert(pre.matrix[row][col] === None);
                        assert(pre.matrix[r_wit][c_wit].is_some());
                        assert(false);
                    }
                };
                assert(post.matrix[r_wit][c_wit] == pre.matrix[r_wit][c_wit]);
            }
        }
    };
}

#[inductive(swing)]
fn swing_inductive(pre: Self, post: Self, key: Key, row: Row, col: Col, row2: Row, col2: Col) {
    assert forall |k: Key| (#[trigger] post.frag[k]).is_some() implies
        exists |r: Row, c: Col|
            0 <= r < HEIGHT && 0 <= c < WIDTH
            && (#[trigger] post.matrix[r][c]).is_some()
            && post.matrix[r][c].unwrap().0 == k
    by {
        if post.frag[k].is_some() {
            // post.frag == pre.frag, so pre.frag[k].is_some()
            assert(pre.frag[k].is_some());
            let r_wit = choose |r: Row| exists |c: Col| 0 <= r < HEIGHT && 0 <= c < WIDTH
                && pre.matrix[r][c].is_some() && pre.matrix[r][c].unwrap().0 == k;
            let c_wit = choose |c: Col| 0 <= r_wit < HEIGHT && 0 <= c < WIDTH
                && pre.matrix[r_wit][c].is_some() && pre.matrix[r_wit][c].unwrap().0 == k;
            if r_wit == row && c_wit == col {
                // The entry moved from (row, col) to (row2, col2)
                assert(post.matrix[row2][col2] == pre.matrix[row][col]);
                assert(post.matrix[row2][col2].is_some());
                assert(post.matrix[row2][col2].unwrap().0 == k);
            } else {
                // pre.matrix[row2][col2] == None, so r_wit != row2 or c_wit != col2
                assert(r_wit != row2 || c_wit != col2) by {
                    if r_wit == row2 && c_wit == col2 {
                        assert(pre.matrix[row2][col2] === None);
                        assert(pre.matrix[r_wit][c_wit].is_some());
                        assert(false);
                    }
                };
                assert(post.matrix[r_wit][c_wit] == pre.matrix[r_wit][c_wit]);
            }
        }
    };
}

