            assert(pre.frag[k].is_some());
            let r_wit = choose |r: Row| exists |c: Col| 0 <= r < HEIGHT && 0 <= c < WIDTH
                && pre.matrix[r][c].is_some() && pre.matrix[r][c].unwrap().0 == k;
            let c_wit = choose |c: Col| 0 <= r_wit < HEIGHT && 0 <= c < WIDTH
                && pre.matrix[r_wit][c].is_some() && pre.matrix[r_wit][c].unwrap().0 == k;
            if r_wit == row && c_wit == col {
                // The entry moved from (row, col) to (row2, col2)
                assert(post.matrix[row2][col2] == pre.matrix[row][col]);
                assert(post.matrix[row2][col2].is_some());
                assert(post.matrix[row2][col2].unwrap().0 == k);
