#[inductive(insert_key_value)]
fn insert_key_value_inductive(pre: Self, post: Self, key: Key, new_val: Value, row: Row, col: Col) {
    assert forall |k: Key| (#[trigger] post.frag[k]).is_some() implies
        exists |r: Row, c: int|
            0 <= r < HEIGHT && 0 <= c < WIDTH
            && (#[trigger] post.matrix[r][c]).is_some()
            && post.matrix[r][c].unwrap().0 == k
    by {
        if post.frag[k].is_some() {
            if k == key {
                assert(post.matrix[row][col as int] == Some((key, new_val)));
            } else {
                let r_wit = choose |r: Row| #[trigger] pre.matrix.dom().contains(r) && exists |c: int| 0 <= r < HEIGHT && 0 <= c < WIDTH
                    && (#[trigger] pre.matrix[r][c]).is_some() && pre.matrix[r][c].unwrap().0 == k;
                let c_wit = choose |c: int| 0 <= r_wit < HEIGHT && 0 <= c < WIDTH
                    && (#[trigger] pre.matrix[r_wit][c]).is_some() && pre.matrix[r_wit][c].unwrap().0 == k;
                assert(r_wit != row || c_wit != col as int) by {
                    if r_wit == row && c_wit == col as int {
                        assert(pre.matrix[row][col as int] === None);
                        assert(pre.matrix[r_wit][c_wit].is_some());
                        assert(false);
                    }
                };
                assert(post.matrix[r_wit][c_wit] == pre.matrix[r_wit][c_wit]);
            }
        }
    };
}

