# Completely rewrite the inductive proofs with a much simpler approach
# Since this is tokenized_state_machine, the pre-state satisfies all invariants
# and we just need to connect the post-state invariant to pre-state

# Strategy: use the invariant directly without explicit choose/witness
# Let Verus handle the witness extraction through assert...by

new_del = '''fn delete_key_value_inductive(pre: Self, post: Self, key: Key, row: Row, col: Col) {
        // key_in_map_implies_key_in_matrix
        assert forall |k: Key| (#[trigger] post.frag[k]).is_some() implies
            exists |r: nat, c: int|
                0 <= r < HEIGHT && 0 <= c < WIDTH
                && (#[trigger] post.matrix[r][c]).is_some()
                && post.matrix[r][c].unwrap().0 == k
        by {
            if (#[trigger] post.frag[k]).is_some() {
                // k != key because post.frag[key] == None
                assert(k != key);
                // pre.frag[k] is some too (unchanged)
                // By pre invariant: get witness (r', c')
                assert(exists |r: nat, c: int|
                    0 <= r < HEIGHT && 0 <= c < WIDTH
                    && (#[trigger] pre.matrix[r][c]).is_some()
                    && pre.matrix[r][c].unwrap().0 == k) by {
                    let witness = choose |rc: (nat, int)|
                        (#[trigger] pre.matrix[rc.0][rc.1]).is_some()
                        && 0 <= rc.0 < HEIGHT && 0 <= rc.1 < WIDTH
                        && pre.matrix[rc.0][rc.1].unwrap().0 == k;
                    assert(pre.matrix[witness.0][witness.1].is_some()
                        && pre.matrix[witness.0][witness.1].unwrap().0 == k);
                };
                // The witness (r', c') from pre satisfies != (row, col) since key != k
                // and at (row, col) the key is `key`
            }
        };
    }'''

